<?php
$adminTitle='Prospect Outreach';
require_once __DIR__.'/../includes/auth.php';require_admin();
require_once __DIR__.'/../includes/outreach_automation.php';require_once __DIR__.'/../includes/audit.php';require_once __DIR__.'/../includes/branding.php';
$pdo=db();$error='';$message='';

function outreach_admin_datetime(?string $value): ?string
{
    $value=trim((string)$value);if($value==='')return null;
    $value=str_replace('T',' ',$value);if(strlen($value)===16)$value.=':00';
    $time=strtotime($value);if(!$time)throw new RuntimeException('The scheduled start date/time is invalid.');
    return date('Y-m-d H:i:s',$time);
}

function outreach_admin_campaign_fields(PDO $pdo,array $input): array
{
    $name=trim((string)($input['campaign_name']??''));$templateId=(int)($input['template_id']??0);
    if($name===''||$templateId<1)throw new RuntimeException('Campaign name and template are required.');
    $stmt=$pdo->prepare('SELECT * FROM supplier_outreach_templates WHERE id=:id LIMIT 1');$stmt->execute(['id'=>$templateId]);$template=$stmt->fetch();if(!$template)throw new RuntimeException('Selected template was not found.');
    $subject=trim((string)($input['campaign_subject_template']??''));$body=trim((string)($input['campaign_body_html']??''));
    if($subject==='')$subject=(string)$template['subject_template'];if($body==='')$body=(string)$template['body_html'];
    if($subject===''||$body==='')throw new RuntimeException('Campaign subject and body are required.');
    return [
        'name'=>$name,'template_id'=>$templateId,'subject_template'=>$subject,'body_html'=>$body,
        'target_supplier_status'=>trim((string)($input['target_supplier_status']??'Prospect'))?:null,
        'target_region'=>trim((string)($input['target_region']??''))?:null,
        'daily_limit'=>max(1,min(50,(int)($input['daily_limit']??10))),
        'min_days_between_contacts'=>max(0,min(365,(int)($input['min_days_between_contacts']??30))),
        'follow_up_days'=>max(1,min(90,(int)($input['follow_up_days']??7))),
        'scheduled_start'=>outreach_admin_datetime($input['scheduled_start']??null),
    ];
}

$campaignEditReady=$pdo&&outreach_campaign_edit_schema_ready($pdo);
if($pdo&&outreach_schema_ready($pdo)&&$_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_valid($_POST['csrf_token']??null))$error='Your session expired.';
    else{try{$action=(string)($_POST['action']??'');$adminId=(int)(admin_user()['id']??0)?:null;
        if($action==='save_template'){
            $id=(int)($_POST['template_id']??0);$name=trim((string)($_POST['name']??''));$subject=trim((string)($_POST['subject_template']??''));$body=trim((string)($_POST['body_html']??''));if($name===''||$subject===''||$body==='')throw new RuntimeException('Template name, subject and body are required.');
            if($id){$pdo->prepare('UPDATE supplier_outreach_templates SET name=:name,subject_template=:subject,body_html=:body,is_active=:active WHERE id=:id')->execute(['name'=>$name,'subject'=>$subject,'body'=>$body,'active'=>isset($_POST['is_active'])?1:0,'id'=>$id]);}
            else{$pdo->prepare('INSERT INTO supplier_outreach_templates(name,subject_template,body_html,is_active) VALUES(:name,:subject,:body,:active)')->execute(['name'=>$name,'subject'=>$subject,'body'=>$body,'active'=>isset($_POST['is_active'])?1:0]);$id=(int)$pdo->lastInsertId();}
            admin_audit($pdo,'outreach.template','supplier_outreach_template',(string)$id,'Saved supplier outreach template');$message='Template saved.';
        }elseif($action==='create_campaign'){
            if(!$campaignEditReady)throw new RuntimeException('Run the campaign preview/editing database upgrade before creating campaigns with editable content.');
            $data=outreach_admin_campaign_fields($pdo,$_POST);
            $pdo->prepare("INSERT INTO supplier_outreach_campaigns(name,template_id,subject_template,body_html,status,target_supplier_status,target_region,daily_limit,min_days_between_contacts,follow_up_days,scheduled_start,created_by) VALUES(:name,:template_id,:subject_template,:body_html,'Draft',:target_supplier_status,:target_region,:daily_limit,:min_days_between_contacts,:follow_up_days,:scheduled_start,:admin)")
                ->execute($data+['admin'=>$adminId]);
            $id=(int)$pdo->lastInsertId();$added=outreach_queue_campaign($pdo,$id);admin_audit($pdo,'outreach.campaign_create','supplier_outreach_campaign',(string)$id,'Created supplier outreach campaign',['queued'=>$added]);$message="Campaign created with $added queued prospect(s).";
            header('Location: outreach.php?campaign='.$id.'&created=1');exit;
        }elseif($action==='update_campaign'){
            if(!$campaignEditReady)throw new RuntimeException('Run the campaign preview/editing database upgrade first.');
            $id=(int)($_POST['campaign_id']??0);if($id<1)throw new RuntimeException('Campaign not found.');
            if(!outreach_campaign_editable($pdo,$id))throw new RuntimeException('This campaign is content-locked because sending has already started. Pause it and create a new campaign for revised content.');
            $data=outreach_admin_campaign_fields($pdo,$_POST);
            $added=outreach_update_campaign_and_rebuild($pdo,$id,$data);admin_audit($pdo,'outreach.campaign_update','supplier_outreach_campaign',(string)$id,'Updated scheduled supplier outreach campaign and rebuilt unsent queue',['queued'=>$added]);
            header('Location: outreach.php?campaign='.$id.'&updated=1');exit;
        }elseif($action==='campaign_status'){
            $id=(int)($_POST['campaign_id']??0);$status=(string)($_POST['status']??'Paused');if(!in_array($status,['Running','Paused'],true))throw new RuntimeException('Invalid campaign status.');$pdo->prepare('UPDATE supplier_outreach_campaigns SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$id]);admin_audit($pdo,'outreach.campaign_status','supplier_outreach_campaign',(string)$id,'Changed campaign status',['status'=>$status]);$message='Campaign status updated.';
        }elseif($action==='queue_campaign'){
            $id=(int)($_POST['campaign_id']??0);$added=outreach_queue_campaign($pdo,$id);$message="$added additional prospect(s) queued.";
        }elseif($action==='process_campaign'){
            $id=(int)($_POST['campaign_id']??0);$result=outreach_process_campaign($pdo,$id,5);admin_audit($pdo,'outreach.process','supplier_outreach_campaign',(string)$id,'Processed outreach batch',$result);$message='Outreach batch processed: '.$result['sent'].' sent, '.$result['failed'].' failed, '.$result['remaining'].' remaining.';
        }
    }catch(Throwable $e){error_log('Moleqra outreach admin failed: '.$e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'Outreach operation failed.';}}
}
$templates=$pdo&&outreach_schema_ready($pdo)?$pdo->query('SELECT * FROM supplier_outreach_templates ORDER BY is_active DESC,name')->fetchAll():[];
$campaigns=$pdo&&outreach_schema_ready($pdo)?$pdo->query("SELECT c.*,t.name template_name,(SELECT COUNT(*) FROM supplier_outreach_queue q WHERE q.campaign_id=c.id) queued,(SELECT COUNT(*) FROM supplier_outreach_queue q WHERE q.campaign_id=c.id AND q.status='Sent') sent,(SELECT COUNT(*) FROM supplier_outreach_queue q WHERE q.campaign_id=c.id AND q.status='Pending') pending,(SELECT COUNT(*) FROM supplier_outreach_queue q WHERE q.campaign_id=c.id AND q.status='Failed') failed,(SELECT COUNT(*) FROM supplier_outreach_queue q WHERE q.campaign_id=c.id AND (q.attempts>0 OR q.status IN ('Sending','Sent'))) attempted FROM supplier_outreach_campaigns c JOIN supplier_outreach_templates t ON t.id=c.template_id ORDER BY c.created_at DESC")->fetchAll():[];
$editTemplate=$templates[0]??null;if(isset($_GET['template'])){foreach($templates as $t)if((int)$t['id']===(int)$_GET['template'])$editTemplate=$t;}
$selectedCampaignId=(int)($_GET['campaign']??0);$selectedCampaign=null;$selectedStats=[];$selectedEditable=false;$selectedPreviewSupplier=[];
if($pdo&&outreach_schema_ready($pdo)&&$selectedCampaignId){$selectedCampaign=outreach_campaign_record($pdo,$selectedCampaignId);if($selectedCampaign){$selectedStats=outreach_campaign_queue_stats($pdo,$selectedCampaignId);$selectedEditable=$campaignEditReady&&outreach_campaign_editable($pdo,$selectedCampaignId);$selectedPreviewSupplier=outreach_preview_supplier($pdo,$selectedCampaignId);}}
$sampleSupplier=$pdo&&outreach_schema_ready($pdo)?outreach_preview_supplier($pdo):['name'=>'Example Supplier','contact_name'=>'Sales Team','email'=>'supplier@example.com','region'=>'South Africa'];
$createTemplate=$templates[0]??['id'=>0,'subject_template'=>'','body_html'=>''];
$templateJs=[];foreach($templates as $t)$templateJs[(string)$t['id']]=['subject'=>(string)$t['subject_template'],'body'=>(string)$t['body_html']];
$brand=branding_settings();$logoPath=branding_logo_path();$baseUrl=rtrim((string)config('base_url',''),'/');$previewLogo=$logoPath!==''?($baseUrl!==''?$baseUrl.'/'.ltrim($logoPath,'/'):'../'.branding_logo_url('')):'';
$previewConfig=['site_name'=>(string)config('site_name','Moleqra'),'contact_email'=>(string)config('contact_email',''),'website'=>$baseUrl,'logo'=>$previewLogo,'background'=>(string)$brand['background_color'],'text'=>(string)$brand['text_color']];
require __DIR__.'/_header.php';
