field"><label>Daily send limit</label><input type="number" name="daily_limit" min="1" max="50" value="<?=(int)$selectedCampaign['daily_limit']?>"<?=$selectedEditable?'':' disabled'?>></div><div class="field"><label>Minimum days between contacts</label><input type="number" name="min_days_between_contacts" min="0" max="365" value="<?=(int)$selectedCampaign['min_days_between_contacts']?>"<?=$selectedEditable?'':' disabled'?>></div><div class="field"><label>Follow-up after days</label><input type="number" name="follow_up_days" min="1" max="90" value="<?=(int)$selectedCampaign['follow_up_days']?>"<?=$selectedEditable?'':' disabled'?>></div><div class="field"><label>Start at</label><input type="datetime-local" name="scheduled_start" value="<?=e($selectedCampaign['scheduled_start']?date('Y-m-d\TH:i',strtotime((string)$selectedCampaign['scheduled_start'])):'')?>"<?=$selectedEditable?'':' disabled'?>></div><?php if($selectedEditable):?><div class="field full"><button class="btn primary">Save campaign &amp; rebuild queue</button></div><?php endif;?></div></form>
