ype="hidden" name="campaign_id" value="<?=(int)$c['id']?>"><button class="link-button">Send next batch</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$campaigns):?><tr><td colspan="6">No campaigns yet.</td></tr><?php endif;?></tbody></table></div></section>
