<script>
(()=>{
const templates=<?=json_encode($templateJs,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const brand=<?=json_encode($previewConfig,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const createSupplier=<?=json_encode(['name'=>$sampleSupplier['name']??'Example Supplier','contact_name'=>$sampleSupplier['contact_name']??'Sales Team'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const editSupplier=<?=json_encode(['name'=>$selectedPreviewSupplier['name']??'Example Supplier','contact_name'=>$selectedPreviewSupplier['contact_name']??'Sales Team'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
function tokens(supplier){const contact=(supplier.contact_name||'').trim();return {'{{supplier_name}}':supplier.name||'','{{contact_name}}':contact,'{{contact_greeting}}':contact||supplier.name||'Sales Team','{{site_name}}':brand.site_name||'Moleqra','{{contact_email}}':brand.contact_email||'','{{website}}':brand.website||''};}
function render(text,supplier){let out=String(text||'');for(const [key,value] of Object.entries(tokens(supplier)))out=out.split(key).join(value);return out;}
function esc(text){return String(text||'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));}
function emailDoc(body){const logo=brand.logo?`<img src="${esc(brand.logo)}" alt="" style="display:block;max-height:46px;max-width:180px;margin-bottom:12px">`:'';return `<!doctype html><html><body style="margin:0;background:#f4f6f8;font-family:Arial,sans-serif;color:#17202a"><div style="max-width:680px;margin:0 auto;padding:28px"><div style="background:${esc(brand.background)};color:${esc(brand.text)};padding:20px 24px;font-weight:700;letter-spacing:.08em">${logo}${esc(brand.site_name)}</div><div style="background:#fff;padding:26px;border:1px solid #dde3ea"><h1 style="font-size:24px;margin:0 0 18px;color:#17202a">Partnership enquiry</h1>${body}<p style="margin-top:28px;color:#65717e;font-size:13px">Research-use-only materials are not for human or veterinary administration.</p></div></div></body></html>`;}
function bindPreview(form,subjectId,frameId,supplier){if(!form)return;const subject=form.querySelector('[name="campaign_subject_template"]');const body=form.querySelector('[name="campaign_body_html"]');const subjectOut=document.getElementById(subjectId);const frame=document.getElementById(frameId);const update=()=>{subjectOut.textContent=render(subject?.value||'',supplier);frame.srcdoc=emailDoc(render(body?.value||'',supplier));};subject?.addEventListener('input',update);body?.addEventListener('input',update);update();}
const createForm=document.getElementById('createCampaignForm');const createSelect=document.getElementById('createTemplate');
if(createForm&&createSelect){const load=()=>{const t=templates[createSelect.value];if(!t)return;createForm.querySelector('[name="campaign_subject_template"]').value=t.subject;createForm.querySelector('[name="campaign_body_html"]').value=t.body;createForm.querySelector('[name="campaign_subject_template"]').dispatchEvent(new Event('input'));createForm.querySelector('[name="campaign_body_html"]').dispatchEvent(new Event('input'));};createSelect.addEventListener('change',load);bindPreview(createForm,'createPreviewSubject','createPreviewFrame',createSupplier);}
const editForm=document.getElementById('editCampaignForm');if(editForm){bindPreview(editForm,'editPreviewSubject','editPreviewFrame',editSupplier);const btn=document.getElementById('loadEditTemplate');const sel=document.getElementById('editTemplate');btn?.addEventListener('click',()=>{const t=templates[sel.value];if(!t)return;if(!confirm('Replace the campaign subject and body with the selected reusable template?'))return;editForm.querySelector('[name="campaign_subject_template"]').value=t.subject;editForm.querySelector('[name="campaign_body_html"]').value=t.body;editForm.querySelector('[name="campaign_subject_template"]').dispatchEvent(new Event('input'));editForm.querySelector('[name="campaign_body_html"]').dispatchEvent(new Event('input'));});}
})();
</script>
<?php endif;?>
